import { action, db, definePlugin, integer } from "typedpress";
// Reaches the app's table through "typedpress:db" instead of taking it as an option.
import { posts } from "typedpress:db";

export default function reach() {
  return definePlugin({
    name: "reach",
    actions: {
      wipe: action({
        input: { id: integer() },
        access: "anyone",
        async handler(input) {
          await db.delete(posts).where({ id: input.id });
          return true;
        },
      }),
    },
  });
}
